import matplotlib.pyplot as plt

def aggregate_predictions(datasets):
    """
    Performs linear regression on each dataset to predict 'value' from 'date',
    aggregates all predictions into a single DataFrame and plots the aggregated
    predictions against the original dates.

    Parameters:
        datasets (list of DataFrame): Each DataFrame must contain 'date' (datetime)
            and 'value' (numeric) columns.

    Returns:
        tuple: (aggregated predictions DataFrame, matplotlib Axes, list of LinearRegression models)

    Raises:
        ValueError: If any dataset is not a DataFrame, lacks required columns,
            or its 'date' column is not in datetime format.
    """
    required_columns = {"date", "value"}

    if not isinstance(datasets, (list, tuple)):
        raise ValueError("'datasets' must be a list of pandas DataFrames.")

    all_dates = []
    all_predictions = []
    models = []

    for i, df in enumerate(datasets):
        if not isinstance(df, pd.DataFrame):
            raise ValueError(f"Dataset at index {i} is not a valid pandas DataFrame.")

        if not required_columns.issubset(df.columns):
            raise ValueError(
                f"Dataset at index {i} must contain 'date' and 'value' columns."
            )

        if not pd.api.types.is_datetime64_any_dtype(df["date"]):
            raise ValueError(
                f"'date' column of dataset at index {i} must be in datetime format."
            )

        X = df["date"].map(pd.Timestamp.toordinal).values.reshape(-1, 1)
        y = df["value"].values

        model = LinearRegression()
        model.fit(X, y)
        predictions = model.predict(X)

        models.append(model)
        all_dates.extend(df["date"].tolist())
        all_predictions.extend(predictions)

    aggregated = pd.DataFrame({
        "date": all_dates,
        "prediction": all_predictions,
    }).sort_values("date").reset_index(drop=True)

    fig, ax = plt.subplots()
    ax.plot(aggregated["date"], aggregated["prediction"], marker="o", linestyle="-")
    ax.set_title("Aggregated Predictions vs Date")
    ax.set_xlabel("Date")
    ax.set_ylabel("Predicted Value")

    return aggregated, ax, models

